#include "../src/codeplugdefinitions.h"
#include <QCoreApplication>
#include <QFile>
#include <QDebug>
int main(int argc,char **argv){QCoreApplication app(argc,argv);QStringList paths; for(int a=1;a<argc;++a) paths.append(QString::fromLocal8Bit(argv[a]));
 if(paths.isEmpty()) paths = {QStringLiteral(WAFFLE_SOURCE_DIR "/Codeplugs/Completed/DM32UV-KD1AHF.data"), QStringLiteral(WAFFLE_SOURCE_DIR "/Codeplugs/Completed/DM32UV-TimzQuickList.data")};
 for(const auto &path:paths){QFile f(path);if(!f.open(QIODevice::ReadOnly))return 1;auto bytes=f.readAll();QString error;ImportedCodeplug plug; if(!CodeplugDefinitions::read(bytes,&plug,&error,"dm32uv.wcp")){qCritical()<<error;return 2;}qInfo()<<path<<"lists"<<plug.scanLists.size()<<"cleanup"<<plug.scanListsNeedCleanup;for(const auto &s:plug.scanLists)qInfo()<<s.name<<s.channelIndexes;QByteArray output;if(!CodeplugDefinitions::write(bytes,plug,plug.radioName,plug.radioId,&output,&error)){qCritical()<<error;return 3;}if(!plug.scanListsNeedCleanup && output!=bytes){qCritical()<<"unchanged export differs";return 4;}ImportedCodeplug again;if(!CodeplugDefinitions::read(output,&again,&error,"dm32uv.wcp")){qCritical()<<error;return 5;}if(again.scanListsNeedCleanup)return 6;if(!plug.scanLists.isEmpty()){plug.scanLists[0].name="Scan test";plug.scanLists[0].channelIndexes={-1,0,2};plug.channels[0].scanListIndex=1;if(!CodeplugDefinitions::write(bytes,plug,plug.radioName,plug.radioId,&output,&error)){qCritical()<<error;return 7;}if(!CodeplugDefinitions::read(output,&again,&error,"dm32uv.wcp")){qCritical()<<error;return 8;}if(again.scanLists[0].name!="Scan test"||again.scanLists[0].channelIndexes!=QVector<int>{-1,0,2}||again.channels[0].scanListIndex!=1)return 9;}qInfo()<<"PASS unchanged/cleanup and edited scan roundtrip";} }
